pragma solidity 0.4.19;

library SafeMath {
function mul(uint256 a, uint256 b) internal constant returns (uint256) {
uint256 c = a * b;
assert(a == 0 || c / a == b);
return c;
}

function div(uint256 a, uint256 b) internal constant returns (uint256) {

uint256 c = a / b;

return c;
}

function sub(uint256 a, uint256 b) internal constant returns (uint256) {
assert(b <= a);
return a - b;
}

function add(uint256 a, uint256 b) internal constant returns (uint256) {
uint256 c = a + b;
assert(c >= a);
return c;
}
}

contract ERC20Basic {
uint256 public totalSupply;
function balanceOf(address who) public constant returns (uint256);
function transfer(address to, uint256 value) public returns (bool);
event Transfer(address indexed from, address indexed to, uint256 value);
}

contract BasicToken is ERC20Basic {
using SafeMath for uint256;

mapping(address => uint256) balances;

function transfer(address _to, uint256 _value) public returns (bool) {
require(_to != address(0));
require(_value > 0 && _value <= balances[msg.sender]);

balances[msg.sender] = balances[msg.sender].sub(_value);
balances[_to] = balances[_to].add(_value);
Transfer(msg.sender, _to, _value);
return true;
}

function balanceOf(address _owner) public constant returns (uint256 balance) {
return balances[_owner];
}
}

contract ERC20 is ERC20Basic {
function allowance(address owner, address spender) public constant returns (uint256);
function transferFrom(address from, address to, uint256 value) public returns (bool);
function approve(address spender, uint256 value) public returns (bool);
event Approval(address indexed owner, address indexed spender, uint256 value);
}

contract StandardToken is ERC20, BasicToken {

mapping (address => mapping (address => uint256)) internal allowed;

function transferFrom(address _from, address _to, uint256 _value) public returns (bool) {
require(_to != address(0));
require(_value > 0 && _value <= balances[_from]);
require(_value <= allowed[_from][msg.sender]);

balances[_from] = balances[_from].sub(_value);
balances[_to] = balances[_to].add(_value);
allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_value);
Transfer(_from, _to, _value);
return true;
}

function approve(address _spender, uint256 _value) public returns (bool) {
allowed[msg.sender][_spender] = _value;
Approval(msg.sender, _spender, _value);
return true;
}

function allowance(address _owner, address _spender) public constant returns (uint256 remaining) {
return allowed[_owner][_spender];
}
}

contract Ownable {
address public owner;

event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

function Ownable() {
owner = msg.sender;
}

modifier onlyOwner() {
require(msg.sender == owner);
_;
}

function transferOwnership(address newOwner) onlyOwner public {
require(newOwner != address(0));
OwnershipTransferred(owner, newOwner);
owner = newOwner;
}

}

contract Pausable is Ownable {
event Pause();
event Unpause();

bool public paused = false;

modifier whenNotPaused() {
require(!paused);
_;
}

modifier whenPaused() {
require(paused);
_;
}

function pause() onlyOwner whenNotPaused public {
paused = true;
Pause();
}

function unpause() onlyOwner whenPaused public {
paused = false;
Unpause();
}
}

contract PausableToken is StandardToken, Pausable {

function transfer(address _to, uint256 _value) public whenNotPaused returns (bool) {
return super.transfer(_to, _value);
}

function transferFrom(address _from, address _to, uint256 _value) public whenNotPaused returns (bool) {
return super.transferFrom(_from, _to, _value);
}

function approve(address _spender, uint256 _value) public whenNotPaused returns (bool) {
return super.approve(_spender, _value);
}

function batchTransfer(address[] _receivers, uint256 _value) public whenNotPaused returns (bool) {
uint cnt = _receivers.length;
uint256 amount = uint256(cnt) * _value;
require(cnt > 0 && cnt <= 20);
require(_value > 0 && balances[msg.sender] >= amount);

balances[msg.sender] = balances[msg.sender].sub(amount);
for (uint i = 0; i < cnt; i++) {
balances[_receivers[i]] = balances[_receivers[i]].add(_value);
Transfer(msg.sender, _receivers[i], _value);
}
return true;
}
}

contract BecToken is PausableToken {

string public name = "BeautyChain";
string public symbol = "BEC";
string public version = '1.0.0';
uint8 public decimals = 18;

function BecToken() {
totalSupply = 7000000000 * (10**(uint256(decimals)));
balances[msg.sender] = totalSupply;
}

function () {

revert();
}
}
```

## Fuzzing task — strategy: reentrancy_probe

**Objective:** Build a transaction sequence in which the attacker-controlled address (attacker_address) ends up with more total value (native coin + tokens) than it spent — i.e. extract funds from the target or break a value invariant in the attacker's favor. Use at most 12 calls per sequence.

**Goal:** Detect reentrancy vulnerabilities (CEI pattern violations).

**Technique:**
Scan the ABI for functions that SEND ETH OUT to msg.sender (typical name patterns: withdraw*, claim*, redeem*, unstake*, cashOut*, emergencyWithdraw*, *ETH, *Funds, harvest*, payout* — but use whatever names this ABI actually has). Configure attacker reentry on one of those functions, fund the contract via a PAYABLE function (typical names: deposit*, stake*, mint*, fund*, buy*, contribute*), then trigger the ETH-sending function so the attacker's receive() callback re-enters. DO NOT default to the names in the example below — they are placeholders.

**Value hints:** Use "0xde0b6b3a7640000" (1 ETH) for payable calls. Use "0x0" for non-payable.

**Valid callers:** "attacker_address"
Use only these alias name(s) in the `caller_name` (msg.sender) slot — there is a
single attacker identity, so every call already runs as the attacker. Never use
"deployer_address" or a raw hex address as a caller. (Address-TYPED ARGUMENTS are
separate: see "Special argument values" below for the aliases those slots accept —
you are NOT restricted to the caller alias there.)
**Strategy notes:** Use "atk.setReentrantCall" as the FIRST call to arm the attacker's re-entry callback: ["atk.setReentrantCall", {"reentrant_func": "fnName", "reentrant_args": ["0x..."], "max_count": 3}, "0x0", "attacker_address"]. The attacker re-enters whenever the target calls BACK into it — either by sending it ETH (receive) or by invoking an unknown selector on it (fallback: e.g. an ERC777/hook/migration callback) — so this covers callback-driven reentrancy too, not just native-ETH transfers. reentrant_func is the function re-called during that callback: a BARE function name from THIS target's ABI (no parentheses, no type list; re-entry always hits the main contract, never an external var). reentrant_args matches that function's input types (use [] if no args). max_count is the re-entry depth (1-5). There is ONE attacker identity: route the arm, the funding/setup AND the final trigger call all through attacker_address (the unified attacker contract) so the callback fires with the attacker as msg.sender.
**Special argument values:**
- address-typed args accept `target_address`, `attacker_address`, or a raw 0x literal.
- `"max"` → uint256 max; `"now"` → block.timestamp.
- `"$ret<idx>"` → feed the RETURN VALUE of the call at 0-based index <idx> in this sequence into this argument (that call must return exactly one value).

**Argument encoding (match each value to its ABI parameter type):**
- uint* / bytesN / bytes → hex string, e.g. "0x1f" (minimal, not zero-padded)
- int* (signed) → decimal string, e.g. "-5"
- bool → true or false (JSON literal, unquoted)
- address → an alias name (see callers/aliases above) or a 40-hex-digit 0x literal
- arrays → JSON list, e.g. [] or ["0x1", "0x2"]; tuples/structs → JSON list of their fields
- empty bytes / empty signature / empty proof → "0x" or []

**Output format:**
Return a JSON array of 1 fuzz input object(s):
[
  {
    "calls": [["functionName", [arg1, arg2], "0x<wei_hex>", "caller_name"], ...],
    "description": "brief description"
  }
]
JSON only — no markdown, no explanation.

**Example sequence:**
```json
Structural pattern (replace UPPERCASE placeholders with real ABI function names):
  [["atk.setReentrantCall", {"reentrant_func": "<ETH_SENDER_FROM_ABI>", "reentrant_args": [], "max_count": 4}, "0x0", "attacker_address"],
   ["<PAYABLE_FUNC_FROM_ABI>", [], "0xde0b6b3a7640000", "attacker_address"],
   ["<PAYABLE_FUNC_FROM_ABI>", [], "0xde0b6b3a7640000", "attacker_address"],
   ["<ETH_SENDER_FROM_ABI>", [], "0x0", "attacker_address"]]
```

